{
  "description": "The image shows a single quadrupedal creature in three-quarter side view facing right against a plain off-white background. It has a broad, flat, pale pink head with a blunt snout, large round eyes and a slightly upturned mouth, with six feathery reddish-brown external gills protruding from behind the head. Its arched back and the dorsal side of its long thick tail are covered in overlapping large brown keratinous scales, while its underside, sides, and four stout limbs are covered in pale pink, moist-looking, heavily wrinkled skin with transverse folds. It stands on four short thick legs with splayed clawed feet, the tail extending to the left out of the frame.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and fleshy with pale pink, slightly bumpy and glossy skin, blunt rounded snout with two small nostrils at the tip, large protruding eyes with golden-brown irises, dark pupils and light blue-grey outer rings, and a closed mouth with a faint smile line",
      "where": "at the front of the body, facing forward and slightly to the right"
    },
    {
      "part": "gills",
      "looks_like": "six feathery external gills, three on each side, each with a central reddish-pink stalk bearing many fine filamentous branches giving a fern-like appearance, dark reddish-brown in color",
      "where": "protruding outward and slightly backward from the neck area immediately behind the head, three on the left side clearly visible and three on the right side partially visible behind the head"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping keratinous scales, rounded to diamond-shaped with darker brown edges and lighter tan centers, showing fine concentric ridges and a glossy texture, arranged in diagonal rows",
      "where": "covering the entire dorsal surface from the base of the gills over the arched back to the dorsal side of the tail"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, stout limbs with pale pink, heavily wrinkled and folded skin, muscular with loose skin around the joints, ending in feet",
      "where": "two forelegs under the chest and two hindlegs under the mid-body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "four splayed feet each with five short toes tipped with small dark brown to black blunt claws, the skin is pink and wrinkled with visible toe pads",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick and tapering, dorsal side covered with the same overlapping brown scales as the back, ventral and lateral sides pale pink and wrinkled, tip extends out of the left edge of the image",
      "where": "extending backward from the rear of the body to the left"
    },
    {
      "part": "markings",
      "looks_like": "no distinct spots or stripes; the ventral skin is uniformly pale pink to off-white with transverse wrinkles and folds along the belly and limbs, and faint darker speckling on the top of the head",
      "where": "on the belly, throat, limbs and top of the head, below the scaled back"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
